"""
Formal Verification & Product UX Deliverable:
Defines the core data structures and invariants for the Agent-Org.
Pydantic models serve as the primary enforcement mechanism for runtime correctness.
"""
from typing import List, Dict, Any, Literal
from pydantic import BaseModel, Field, conint, model_validator, StrictFloat, ValidationError

# A constrained integer type for department count, enforcing the 3-7 rule.
# This is a direct implementation of a formal invariant.
DepartmentCount = conint(ge=3, le=7)

class KeyResult(BaseModel):
    """A quantifiable outcome for an Objective."""
    metric: str = Field(..., min_length=1, description="The metric to measure, e.g., 'p99_latency_ms'.")
    target: StrictFloat = Field(..., description="The target value for the metric. Must be a finite float.")
    # The operator ensures the goal is unambiguous.
    operator: Literal["<", ">", "<=", ">=", "=="] = Field(..., description="Operator to compare actual vs. target.")

class OKR(BaseModel):
    """An Objective and its associated Key Results."""
    objective: str = Field(..., min_length=1, description="A high-level, qualitative goal.")
    key_results: List[KeyResult] = Field(..., min_length=1)

class Department(BaseModel):
    """A functional unit within the organization."""
    id: str = Field(..., min_length=1, description="Unique identifier for the department, e.g., 'systems_eng'.")
    role: str = Field(..., min_length=1, description="A description of the department's function.")
    okrs: List[OKR] = Field(default_factory=list)

class OrgManifest(BaseModel):
    """
    The complete 'genome' of the agent organization.
    This is the single source of truth for the org's structure and goals.
    """
    version: str = Field("0.1.0", description="The version of the manifest schema.")
    org_id: str = Field(..., min_length=1, description="A unique identifier for this organization instance.")
    departments: List[Department]

    @model_validator(mode='after')
    def check_department_count(self) -> 'OrgManifest':
        """
        Ensures the number of departments is within the allowed range [3, 7].
        This is a critical organizational invariant.
        """
        num_departments = len(self.departments)
        # Directly use the integer bounds instead of trying to access attributes from conint type
        if not (3 <= num_departments <= 7):
            raise ValueError(f"Organization must have between 3 and 7 departments, found {num_departments}.")
        return self

    @model_validator(mode='after')
    def check_unique_department_ids(self) -> 'OrgManifest':
        """Ensures all department IDs are unique."""
        department_ids = [dept.id for dept in self.departments]
        if len(department_ids) != len(set(department_ids)):
            raise ValueError("All department IDs must be unique.")
        return self

    @model_validator(mode='after')
    def check_okr_uniqueness(self) -> 'OrgManifest':
        """Ensures that within each department, OKR objectives are unique."""
        for department in self.departments:
            objectives = [okr.objective for okr in department.okrs]
            if len(objectives) != len(set(objectives)):
                raise ValueError(f"Duplicate OKR objectives found in department '{department.id}'.")
        return self

    @model_validator(mode='after')
    def check_key_result_uniqueness(self) -> 'OrgManifest':
        """Ensures that within each OKR, key result metrics are unique."""
        for department in self.departments:
            for okr in department.okrs:
                metrics = [kr.metric for kr in okr.key_results]
                if len(metrics) != len(set(metrics)):
                    raise ValueError(
                        f"Duplicate Key Result metrics found for objective '{okr.objective}' "
                        f"in department '{department.id}'."
                    )
        return self

    def get_department(self, department_id: str) -> Department:
        """Retrieves a department by its ID."""
        for department in self.departments:
            if department.id == department_id:
                return department
        raise ValueError(f"Department with ID '{department_id}' not found.")

    def get_okrs_for_department(self, department_id: str) -> List[OKR]:
        """Retrieves all OKRs for a given department."""
        department = self.get_department(department_id)
        return department.okrs

    def get_key_results_for_objective(self, department_id: str, objective: str) -> List[KeyResult]:
        """Retrieves key results for a specific objective within a department."""
        department = self.get_department(department_id)
        for okr in department.okrs:
            if okr.objective == objective:
                return okr.key_results
        raise ValueError(f"Objective '{objective}' not found in department '{department_id}'.")
